"""FIPS-mode password hashing API using PBKDF2-HMAC only."""

from __future__ import annotations

import pbkdf2_hasher as _pbkdf2


def fips_password_hash(password: str, digest: str) -> str:
    """
    Hash a password for the FIPS subsystem using PBKDF2-HMAC.

    Supported digests for new hashes: sha256, sha512.
    sha1 is accepted for legacy verification only and must not be used for new hashes.
    """
    if digest == "sha1":
        raise PermissionError("PBKDF2-HMAC-SHA1 is legacy only and must not be used for new hashes")
    return _pbkdf2.hash_pbkdf2(password, digest)


def fips_verify(password: str, stored: str) -> bool:
    """Verify a password against any stored PBKDF2-HMAC hash."""
    return _pbkdf2.verify_pbkdf2(password, stored)
